"""Postexit causal native IMU qualification/pose gate, no replay or model adjustment."""
from pathlib import Path
import datetime,json,hashlib
from collections import Counter
import numpy as np
from scipy.spatial.transform import Rotation
H=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=json.loads((H/'native_imu_protocol.json').read_text());status=json.loads((H/'native_imu_status.json').read_text());assert status['status']=='finished' and status['exit_code']==0;out=H/'native_imu_run';m=json.loads((out/'artifact_manifest_post_close.json').read_text());checks=0
 for obj,key in [(p,'source_sha256'),(p,'baseline_artifacts'),(m,'artifact_sha256')]:
  for f,s in obj[key].items():assert sha(f)==s,f;checks+=1
 reads=json.loads((out/'native_imu_reads.json').read_text());packets=json.loads((out/'native_imu_packets.json').read_text());pred=json.loads((out/'native_imu_predictions.json').read_text());z=np.load(out/'physics.npz');old=np.load(H/'shell_link_run/physics.npz');t=z['simulation_time_s'];assert len(reads)==len(packets)==len(pred)==len(t);assert np.array_equal([r['time_s'] for r in reads],t) and np.array_equal([r['time_s'] for r in pred],t)
 for q in packets:
  if q is not None:assert set(q)=={'time_s','gyro_body_rad_s','linear_acceleration_body_m_s2','main_encoder_rad_s'} and all(np.isfinite(np.asarray(v)).all() for v in q.values())
 assert all(not r['orientation_read'] for r in reads)
 availability=np.array([r['available'] for r in pred]);qualified=np.array([r['qualified'] for r in reads]);assert np.array_equal(availability,qualified)
 iface=all(r['qualified'] or (r['time_s']<=.04 and r['reason']=='invalid') for r in reads)
 equality={k:old[k].shape==z[k].shape and bool(np.array_equal(old[k],z[k],equal_nan=True)) for k in old.files if k not in ['raw_simulation_time_s','raw_physics_step_index']};assert len(equality)==17
 q=z['root_quaternion_world_wxyz'];R=Rotation.from_quat(q[:,[1,2,3,0]]).as_matrix();actual=(z['root_position_world_m']-z['root_position_world_m'][0])@R[0];relative=R[0].T[None]@R;valid=t>=1;available_eval=valid&availability;complete=bool(availability[valid].all());pe=np.full(len(t),np.nan);ae=np.full(len(t),np.nan);estpos=np.full((len(t),3),np.nan)
 if availability.any():
  estimate=np.array([r['rotation'] for r in pred if r['available']]);positions=np.array([r['position'] for r in pred if r['available']]);estpos[availability]=positions;pe[availability]=np.linalg.norm(positions-actual[availability],axis=1);ae[availability]=np.degrees(Rotation.from_matrix(np.transpose(relative[availability],(0,2,1))@estimate).magnitude())
 rms=float(np.sqrt(np.mean(pe[available_eval]**2))) if available_eval.any() else None;peak=float(pe[available_eval].max()) if available_eval.any() else None;ang=float(np.percentile(ae[available_eval],90)) if available_eval.any() else None
 gates=dict(complete_evaluation=complete,translation_rms=rms is not None and rms<=.05,translation_peak=peak is not None and peak<=.1,attitude_p90=ang is not None and ang<=2)
 acc=np.asarray([r['linear_acceleration_body_m_s2'] for r in reads]);norm=np.linalg.norm(acc,axis=1);expected=(np.transpose(R,(0,2,1))@np.array([0.,0.,1.])[:,None])[...,0];acc_dir=np.divide(acc,norm[:,None],out=np.zeros_like(acc),where=norm[:,None]>0);angle=np.degrees(np.arccos(np.clip(np.sum(acc_dir*expected,axis=1),-1,1)));used=np.array([bool(r.get('gravity_used',False)) for r in pred]);used_eval=valid&used
 result=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),actual_status=status,integrity_checks=checks,source_count=len(p['source_sha256']),postclose_artifacts=len(m['artifact_sha256']),physics_rows=len(t),native_read_rows=len(reads),qualified_rows=int(qualified.sum()),unqualified_reasons=dict(Counter(r['reason'] for r in reads if not r['qualified'])),interface_pass=iface,time_age_peak_s=max(abs(r['age_s']) for r in reads if r['age_s'] is not None),gyro_match_peak_rad_s=max(r['gyro_comparison_error_rad_s'] for r in reads if r['gyro_comparison_error_rad_s'] is not None),startup_unqualified=[dict(time_s=r['time_s'],reason=r['reason']) for r in reads if not r['qualified'] and r['time_s']<=.04],evaluated_denominator=int(valid.sum()),evaluated_available=int(available_eval.sum()),full_prediction_coverage=complete,translation_rms_m=rms,translation_peak_m=peak,attitude_p90_deg=ang,pose_gates=gates,pose_candidate_pass=bool(iface and all(equality.values()) and all(gates.values())),baseline_exact_nonraw=equality,baseline_exact_nonraw_all=all(equality.values()),raw_time_delta=np.unique(z['raw_simulation_time_s']-old['raw_simulation_time_s']).tolist() if z['raw_simulation_time_s'].shape==old['raw_simulation_time_s'].shape else None,gravity_used_evaluation=int(used_eval.sum()),gravity_direction_vs_GT_p90_deg=float(np.percentile(angle[used_eval],90)) if used_eval.any() else None,acceleration_norm_min_max=[float(norm.min()),float(norm.max())],gravity_comparison_is_label_diagnostic_not_input=True,metrics=json.loads((out/'metrics.json').read_text()),physical_episodes=1,new_fits=0,parameters_retuned=False,fresh_whole_sequence_validation=False,formal_e0e1e2_run=False,estimator_used_by_control=False,rgb_source_gate_pass=False,whole_research_complete=False)
 np.savez_compressed(H/'native_imu_measurement.npz',time_s=t,available=availability,position_error_m=pe,attitude_error_deg=ae,predicted_position=estpos,actual_position=actual,acceleration_norm=norm,gravity_used=used,acceleration_direction_label_angle_deg=angle)
 (H/'native_imu_audit.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n');print(json.dumps({k:result[k] for k in ['physics_rows','interface_pass','unqualified_reasons','evaluated_denominator','evaluated_available','translation_rms_m','translation_peak_m','attitude_p90_deg','pose_candidate_pass','baseline_exact_nonraw_all','gravity_direction_vs_GT_p90_deg']},indent=2))
if __name__=='__main__':main()
